window.ScripturaLexicons.BDAG_PART_0253 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-01\" data-source=\"BDAG\" data-search=\"ὀλέθριος, ον adjetivo mortífero; destrutivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλέθριος, ον</td><td>adjetivo</td><td>mortífero; destrutivo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-02\" data-source=\"BDAG\" data-search=\"ὄλεθρος, ου, ὁ substantivo masculino destruição; ruína; morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄλεθρος, ου, ὁ</td><td>substantivo masculino</td><td>destruição; ruína; morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-03\" data-source=\"BDAG\" data-search=\"ὀλιγόβιος, ον adjetivo de vida curta; efêmero BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλιγόβιος, ον</td><td>adjetivo</td><td>de vida curta; efêmero</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-04\" data-source=\"BDAG\" data-search=\"ὀλιγοπιστία, ας, ἡ substantivo feminino pobreza de fé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλιγοπιστία, ας, ἡ</td><td>substantivo feminino</td><td>pobreza de fé</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-05\" data-source=\"BDAG\" data-search=\"ὀλιγόπιστος, ον adjetivo de pouca fé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλιγόπιστος, ον</td><td>adjetivo</td><td>de pouca fé</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-06\" data-source=\"BDAG\" data-search=\"ὀλίγος, η, ον adjetivo poucos; pequeno; breve BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλίγος, η, ον</td><td>adjetivo</td><td>poucos; pequeno; breve</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-07\" data-source=\"BDAG\" data-search=\"ὀλιγοχρόνιος, ον adjetivo de curta duração BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλιγοχρόνιος, ον</td><td>adjetivo</td><td>de curta duração</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-08\" data-source=\"BDAG\" data-search=\"ὀλιγοψυχέω verbo desanimar; perder o ânimo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλιγοψυχέω</td><td>verbo</td><td>desanimar; perder o ânimo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-09\" data-source=\"BDAG\" data-search=\"ὀλιγόψυχος, ον adjetivo desanimado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλιγόψυχος, ον</td><td>adjetivo</td><td>desanimado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-10\" data-source=\"BDAG\" data-search=\"ὀλιγωρέω verbo menosprezar; fazer pouco caso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλιγωρέω</td><td>verbo</td><td>menosprezar; fazer pouco caso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-11\" data-source=\"BDAG\" data-search=\"ὀλίγως advérbio dificilmente; por pouco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλίγως</td><td>advérbio</td><td>dificilmente; por pouco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-12\" data-source=\"BDAG\" data-search=\"ὄλλυμι verbo destruir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὄλλυμι</td><td>verbo</td><td>destruir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-13\" data-source=\"BDAG\" data-search=\"ὀλοθρευτής, οῦ, ὁ substantivo masculino destruidor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλοθρευτής, οῦ, ὁ</td><td>substantivo masculino</td><td>destruidor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-14\" data-source=\"BDAG\" data-search=\"ὀλοθρεύω verbo destruir; arruinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλοθρεύω</td><td>verbo</td><td>destruir; arruinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-15\" data-source=\"BDAG\" data-search=\"ὁλοκαύτωμα, ατος, τό substantivo neutro holocausto; sacrifício inteiramente queimado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁλοκαύτωμα, ατος, τό</td><td>substantivo neutro</td><td>holocausto; sacrifício inteiramente queimado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-16\" data-source=\"BDAG\" data-search=\"ὁλοκληρία, ας, ἡ substantivo feminino integridade; inteireza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁλοκληρία, ας, ἡ</td><td>substantivo feminino</td><td>integridade; inteireza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-17\" data-source=\"BDAG\" data-search=\"ὁλόκληρος, ον adjetivo inteiro; completo; irrepreensível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁλόκληρος, ον</td><td>adjetivo</td><td>inteiro; completo; irrepreensível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-18\" data-source=\"BDAG\" data-search=\"ὀλολύζω verbo clamar; gritar em voz alta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὀλολύζω</td><td>verbo</td><td>clamar; gritar em voz alta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-19\" data-source=\"BDAG\" data-search=\"ὅλος, η, ον adjetivo todo; inteiro; completo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὅλος, η, ον</td><td>adjetivo</td><td>todo; inteiro; completo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0253-20\" data-source=\"BDAG\" data-search=\"ὁλοτελής, ές adjetivo completo em todos os aspectos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὁλοτελής, ές</td><td>adjetivo</td><td>completo em todos os aspectos</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0253-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλέθριος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλέθριος</span>, <span class=\"greek\">ον</span> (ver artigo seguinte; Hom. e outros; ver Crönert 186; LXX), em sentido ativo (assim na maioria dos casos, inclusive Polyb. 2, 68, 10; 3 Km 21:42), relativo ao que causa destruição completa, mortífero, destrutivo: <span class=\"greek\">τίνειν</span> <span class=\"greek\">ὀλέθριον</span> <span class=\"greek\">δίκην</span>, sofrer punição letal, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:9</a>, variante de leitura.—DELG s.v. <span class=\"greek\">ὄλλυμι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄλεθρος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄλεθρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὄλλυμι</span>, «destruir»; Hom. e posteriores; SIG 527, 82 [c. 220 a.C.]; BGU 1027 XXVI, 11; LXX; PsSol 8:1; TestReub 4:6; 6:3; Philo; Jos., Ant. 17, 38, Vi. 264; SibOr 3, 327; 348). ① Estado de destruição, destruição, ruína, morte; em nossa literatura, sempre com alguma conotação transcendente (espíritos hostis agem <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ὀλέθρῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">γένους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>, para destruição da raça humana, Orig., C. Cels. 8, 54, 32): <span class=\"greek\">ἔρχεταί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ὄλ</span>., a ruína sobrevém a alguém, 1 Cl 57:4 (Pr 1:26). <span class=\"greek\">αἰφνίδιος</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">ἐφίσταται</span> <span class=\"greek\">ὄλ</span>., destruição súbita lhes sobrevirá, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:3</a>. <span class=\"greek\">βυθίζειν</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὄλ</span>., precipitar alguém na ruína, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:9</a>. <span class=\"greek\">ὄλ</span>. <span class=\"greek\">αἰώνιος</span>, morte eterna (TestReub 6:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:9</a> (ver <span class=\"greek\">ὀλέθριος</span>). ② Ato de destruir, destruição: <span class=\"greek\">παραδοῦναί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σατανᾷ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὄλ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκός</span>, entregar alguém a Satanás para destruição de sua carne, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:5</a> (a entrega a Satanás resultará na morte do pecador.—EvDobschütz, Die urchristl. Gemeinden 1902, 269–72; Lietzmann, Hdb. ’49, 28; e ver <span class=\"greek\">παραδίδωμι</span> 1b.—Hierocles 14, 451b apresenta a ideia de que a alma do pecador no Hades é purificada pelos tormentos do inferno e, desse modo, salva). A destruição causada por Satanás também é mencionada em IEph 13:1: <span class=\"greek\">ὅταν</span> <span class=\"greek\">πυκνῶς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">γίνεσθε</span>, <span class=\"greek\">καθαιροῦνται</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σατανᾶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λύεται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ὄλ</span>. <span class=\"greek\">αὐτοῦ</span>, quando vos reunis frequentemente, os poderes (espirituais) de Satanás são destruídos e sua atividade destruidora é anulada.—DELG s.v. <span class=\"greek\">ὄλλυμι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλιγόβιος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλιγόβιος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὀλίγος</span>, <span class=\"greek\">βίος</span>; Aristot., HA 8, 28; Sext. Emp., Math. 1, 73; Job), de vida curta, efêmero: <span class=\"greek\">γεννητὸς</span> <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">ὀλ</span>., aquele que nasceu de mulher e tem vida curta, 1 Cl 30:5 (Job 11:2).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλιγοπιστία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλιγοπιστία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (cf. <span class=\"greek\">ἀπιστία</span> e ver artigo seguinte; somente em escritores cristãos; Leontius 7 p. 14, 18; 21; 15, 6; Cos. and Dam. 26, 71; ver RAC XI 48–122): pequenez ou pobreza de fé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:20</a>.—DELG s.v. <span class=\"greek\">πείθομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλιγόπιστος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλιγόπιστος</span>, <span class=\"greek\">ον</span> (ver artigo precedente; Sextus 6; de resto, somente em escritores cristãos, por exemplo AcThom 28 [Aa II 2 p. 145]), de pouca fé ou confiança; em nossa literatura, no NT, apenas nos Sinóticos, e somente em interpelações dirigidas aos discípulos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:30</a>; 8:26; 16:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:28</a>; somente a Pedro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:31</a>.—Aos cristãos em Corinto, AcPlCor 2:31.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλίγος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλίγος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hom. e posteriores.—No NT, a grafia <span class=\"greek\">ὁλίγος</span> não é atestada raramente [exemplos em B-D-F § 14; Mlt-H., 98f; cf. Schwyzer I 226; II 201]; como <span class=\"greek\">ἑλπίς</span>, <span class=\"greek\">ἵδιος</span> e algumas outras formas desse tipo, essa grafia aparece em inscrições e papiros já em época pré-cristã, tornando-se mais frequente posteriormente [Crönert 148–53; Helbing 25f; Thackeray 126f; Hauser 60]). ① Relativo a algo comparativamente pequeno em número, poucos, plural. ⓐ Empregado com substantivo: <span class=\"greek\">ἐργάται</span>, trabalhadores, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:2</a>. <span class=\"greek\">ἰχθύδια</span>, alguns peixinhos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:7</a>. <span class=\"greek\">ἄρρωστοι</span>, doentes, 6:5. <span class=\"greek\">ἄφρονες</span>, alguns insensatos, ITr 8:2. <span class=\"greek\">ὀνόματα</span>, nomes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:4</a>. <span class=\"greek\">πρόσωπα</span>, pessoas, 1 Cl 1:1. Com <span class=\"greek\">κεράμια</span>, a subentender pelo contexto imediato, Hm 12, 5, 3. <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">ὀλίγαι</span> (PFay 123, 10 [c. 100 d.C.]; Gen 29:20; cf. Ps 108:8; Philo, Somn. 1, 46; Jos., Ant. 1, 91): <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">ὀλίγαις</span> (Diod S 36, 4, 4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:30</a> D. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὀλ</span>. <span class=\"greek\">ἡμέρας</span>, por poucos dias, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:10</a>; <span class=\"greek\">μετὰ</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ὀλ</span>., depois de poucos dias, Hs 7:1; 8, 4, 1. <span class=\"greek\">μετ</span>’ <span class=\"greek\">ὀλ</span>. <span class=\"greek\">ἡμέρας</span> (Teles p. 19, 5; Diod S 13, 8, 1), 8, 11, 5; 9, 5, 5f. <span class=\"greek\">μετὰ</span> <span class=\"greek\">ὀλ</span>. <span class=\"greek\">ἡμέρας</span>, 5, 2, 9; 8, 2, 9. <span class=\"greek\">ὀλ</span>. <span class=\"greek\">ῥήματα</span>, poucas palavras, m 4, 2, 1; 12, 5, 1. <span class=\"greek\">δι</span>’ <span class=\"greek\">ὀλ</span>. <span class=\"greek\">γραμμάτων</span>, em poucas linhas (ver <span class=\"greek\">γράμμα</span> 1), IRo 8:2; IPol 7:3. ⓑ De modo absoluto: <span class=\"greek\">ὀλίγοι</span>, (uns) poucos (em oposição a <span class=\"greek\">πολλοί</span>, como em Menand., Mon. 670 Jäkel [443 Meineke]; Polyb. 18, 53, 1; Diod S 15, 37, 1; Plut., Mor. 188e; Porphyr., Vi. Pyth. 22; Tat. 3, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:14</a> (Cebes 15, 2f, são <span class=\"greek\">ὀλίγοι</span> aqueles que percorrem o <span class=\"greek\">στενὴ</span> <span class=\"greek\">ὁδός</span> …, <span class=\"greek\">ἡ</span> <span class=\"greek\">ἄγουσα</span>, caminho estreito que conduz ao destino; TestAbr A 11 p. 90, 11 [Stone p. 28] <span class=\"greek\">ὀλίγοι</span> … <span class=\"greek\">οἱ</span> <span class=\"greek\">σῳζόμενοι</span>); 20:16, variante de leitura; 22:14 = 4:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:23</a>.—Uns poucos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:20</a>; MPol 5:1 (cf. Just., A I, 44, 13). Empregado com genitivo partitivo (Arrian, Anab. 5, 15, 4 <span class=\"greek\">ὀλίγοι</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐλεφάντων</span>) e negação: não poucos, certo número (de) (Jos., Bell. 7, 438): <span class=\"greek\">γυναικῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:4</a>; <span class=\"greek\">γυναικῶν</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀνδρῶν</span>, versículo 12.—<span class=\"greek\">ὀλ</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτῶν</span>, Hs 9, 8, 6.—<span class=\"greek\">ὀλίγα</span>, poucas coisas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:42</a>, variante de leitura (em oposição a <span class=\"greek\">πολλά</span>, como em Menand., Mon. 311 Jäkel [226 Meineke]; Ath. 12, 3; ver ABaker, CBQ 27, ’65, 127–37); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:14</a>; <span class=\"greek\">ὑποδείξω</span> <span class=\"greek\">ὀλ</span>., indicarei algumas coisas, 1:8. <span class=\"greek\">ὀλ</span>. <span class=\"greek\">ἐπερωτᾶν</span> <span class=\"greek\">τινα</span>, fazer algumas perguntas a alguém, Hm 4, 1, 4. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ὀλίγα</span> <span class=\"greek\">ἦς</span> <span class=\"greek\">πιστός</span>, foste fiel na administração de poucas coisas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:21</a>, 23. <span class=\"greek\">δαρήσεται</span> <span class=\"greek\">ὀλίγας</span>, receberá poucos açoites, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:48</a> (ver <span class=\"greek\">δέρω</span>). <span class=\"greek\">δι</span>’ <span class=\"greek\">ὀλίγων</span> <span class=\"greek\">γράφειν</span>, escrever brevemente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:12</a> (<span class=\"greek\">βραχέων</span> P 72, cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:22</a>; ver <span class=\"greek\">διά</span> A 3b). ② Relativo a algo relativamente pequeno numa escala de extensão, pouco, pequeno, breve, singular. ⓐ Quantidade (3 Km 17:10 <span class=\"greek\">ὀλ</span>. <span class=\"greek\">ὕδωρ</span>): <span class=\"greek\">οἶνος</span> <span class=\"greek\">ὀλ</span>., um pouco de vinho (Artem. 1, 66 p. 59, 25), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:23</a>; <span class=\"greek\">πῦρ</span> <span class=\"greek\">ὀλ</span>., um pequeno fogo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:5</a>, variante de leitura. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὀλ</span>. <span class=\"greek\">ἐργασία</span>, lucro considerável, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:24</a>; quanto ao fruto, pouco, Hs 2:4; quanto a um país, pequeno, 1 Cl 10:2.—Substantivado: <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀλίγον</span>, uma pequena quantidade; <span class=\"greek\">ὁ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὀλ</span>., aquele que recolheu pouco (em oposição a <span class=\"greek\">ὁ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πολύ</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:15</a> (cf. Num 11:32; Ex 16:18). <span class=\"greek\">ᾧ</span> <span class=\"greek\">ὀλίγον</span> <span class=\"greek\">ἀφίεται</span>, aquele a quem pouco é perdoado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:47a</a> (cf. o emprego no versículo 47b e ver 3 adiante). ⓑ Duração: <span class=\"greek\">α</span>. (Musaeus versículo 291 <span class=\"greek\">ὀλίγον</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">χρόνον</span> = por breve tempo; TestAbr B 2 p. 106, 5 [Stone p. 60] <span class=\"greek\">ὀλίγην</span> <span class=\"greek\">ὥραν</span>) <span class=\"greek\">ὀλ</span>. <span class=\"greek\">καιρός</span>, breve tempo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:12</a>. <span class=\"greek\">χρόνος</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὀλ</span>., longo tempo (Jos., Bell. 2, 62), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:28</a>. <span class=\"greek\">ὀλίγον</span> <span class=\"greek\">χρόνον</span>, por pouco tempo (Menand., Fgm. 567 Kö.), 2 Cl 19:3; Hs 7:6; <span class=\"greek\">ἐν</span> <span class=\"greek\">καιρῷ</span> <span class=\"greek\">ὀλ</span>., em breve tempo, 1 Cl 23:4. <span class=\"greek\">β</span>. O neutro <span class=\"greek\">ὀλίγον</span> empregado adverbialmente (Hom. e outros; Pr 6:10; Sir 51:16, 27) com preposições, em breve tempo, rapidamente (Pind.; Pla., Apol. 22b; Jos., Ant. 18, 145; Lucian, Toxaris 24), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:28</a> (ver <span class=\"greek\">πείθω</span> 1b; 3a e referências ali). <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀλ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μεγάλῳ</span>, quer em pouco, quer em muito tempo, versículo 29 (ver B-D-F § 195; GWhitaker, The Words of Agrippa to St. Paul: JTS 15, 1914, 82f; AFridrichsen, SymbOsl 14, ’35, 50; Field, Notes 141–43; ver Rob. 653).—<span class=\"greek\">μετ</span>’ <span class=\"greek\">ὀλίγον</span>, depois de pouco tempo (Diod S 14, 9, 6; 15, 6, 5; Appian, Liby. 98 §465; SIG 1170, 25f; PRyl 77, 41; Jdth 13:9; Wsd 15:8; TestAbr A 7 p. 84, 8 [Stone p. 16]; GrBar 9:3; Jos., Vi. 344; Just., D. 56, 18), MPol 11:2.—<span class=\"greek\">πρὸς</span> <span class=\"greek\">ὀλίγον</span>, por breve tempo (Lucian, Dial. Deor. 18, 1; Aelian, VH 12, 63; POxy 67, 14; Jos., Bell. 4, 642, Ant. 4, 128; Just., A I, 12, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:14</a>.—Sem preposição (Ps 36:10; TestJob 40:4; ParJer 5:2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:6</a>; 5:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:10</a>. ⓒ Distância: o neutro <span class=\"greek\">ὀλίγον</span> usado adverbialmente, um pouco, quanto à distância etc. (Pla., Prot. 26, 339d <span class=\"greek\">ὀλίγον</span> <span class=\"greek\">προελθών</span>; ApcMos 19 <span class=\"greek\">περιπατήσας</span> <span class=\"greek\">ὀλίγον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:3</a>. ③ Relativamente baixo numa escala de extensão ou presente somente em pequeno grau, pouco, ligeiro: <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὀλ</span>., grande, grave: <span class=\"greek\">τάραχο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:18</a>; 19:23. <span class=\"greek\">στάσις</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ζήτησις</span>, 15:2. <span class=\"greek\">χειμών</span>, 27:20.—Só um pouco (Ael. Aristid. 33, 6 K.=51 p. 573 D.): <span class=\"greek\">ὀλίγον</span> <span class=\"greek\">ἀγαπᾷ</span>, ele ama somente em pequena medida, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:47b</a>.—Com preposição: <span class=\"greek\">ἐν</span> <span class=\"greek\">ὀλίγῳ</span> (cf. TestGad 4:6 = «ligeiramente»), em poucas palavras (Aristot., Rhet. 3, 11 p. 1412b, 23; Dionys. Byz. §3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:3</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὀλίγον</span> <span class=\"greek\">ὠφέλιμος</span>, útil em pequena medida (= tem algum valor), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:8</a>. GJs19, 2 (ver deStrycker 279).—B. 925f. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλιγοχρόνιος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλιγοχρόνιος</span>, <span class=\"greek\">ον</span> (Hdt. e outros; Polyb. 2, 35, 6; Epict. em Stob. p. 463, 1 Sch.; frequentemente Vett. Val., ver índice; Wsd 9:5; Philo), de curta duração, efêmero: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπιδημία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">ταύτης</span> <span class=\"greek\">μικρά</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὀλ</span>., «a permanência desta carne neste mundo é breve e de curta duração», 2 Cl 5:5. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐνθάδε</span> (com <span class=\"greek\">μικρά</span> e <span class=\"greek\">φθαρτά</span>), 6:6.—DELG s.v. <span class=\"greek\">ὀλίγο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλιγοψυχέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλιγοψυχέω</span> (Isocr. 19, 39; inscrições da Panfília: JHS 32, 1912, 273; PPetr II, 40 [a], 12; UPZ 63, 1 [158 a.C.]; POxy 1294, 13; LXX; JosAs 11 [p. 53, 8 Bat.] cód. A), em oposição a <span class=\"greek\">ἀνδρίζομαι</span>, ter o ânimo abatido, desanimar: <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀλιγοψυχοῦντες</span>, os desanimados, 1 Cl 59:4.—Cf. DELG s.v. <span class=\"greek\">ψυχή</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλιγόψυχος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλιγόψυχος</span>, <span class=\"greek\">ον</span> (Artem. 3, 5; PMilan [I ’37] 24, 50 [117 d.C.] <span class=\"greek\">ὀλιόψυχος</span> [sic], de uma mulher; LXX; cf. Cat. Cod. Astr. X 222, 16; 226, 8), de ânimo abatido, desanimado, como substantivo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:14</a>.—DELG s.v. <span class=\"greek\">ὀλίγο</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλιγωρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλιγωρέω</span> (<span class=\"greek\">ὀλίγος</span>, <span class=\"greek\">ὤρα</span>, «cuidado»), aoristo do subjuntivo, 3ª pessoa singular, <span class=\"greek\">ὀλιγωρήσῃ</span>, ParJer 5:5 (Thu. e outros; inscrições, papiros; PsSol 3:4; TestJob 13:5; ParJer), ter pouca consideração por algo, menosprezar, fazer pouco caso, com <span class=\"greek\">τινός</span>, de algo (Diod S 1, 39, 13 <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>; 8, 30, 1 <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐσεβείας</span>; 20, 14, 2 <span class=\"greek\">τοῦ</span> <span class=\"greek\">δαιμονίου</span>; PFlor 384, 86; Philo; Jos., Ant. 5, 132, C. Ap. 2, 172.—B-D-F § 176, 2; Rob. 508), <span class=\"greek\">παιδείας</span> <span class=\"greek\">κυρίου</span>, da disciplina do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:5</a> (Pr 3:11; cf. SEG XXVII, 261 B, 19 <span class=\"greek\">παιδοτριβῶν</span>; ver New Docs 2, 105).—DELG s.v. <span class=\"greek\">ὤρα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλίγως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλίγως</span>, advérbio de <span class=\"greek\">ὀλίγος</span> (Hippocr., Aphorisms 2, 7; Ps.-Pla., Alcibiades II 149a, variante de leitura; Strato [II d.C.]: Anth. Pal. 12, 205, 1; OGI 669 II, 11: <span class=\"greek\">ὀλ</span>[<span class=\"greek\">ίγ</span>]<span class=\"greek\">ω</span>[<span class=\"greek\">ι</span>] no texto; ver nota 20 sobre a leitura <span class=\"greek\">ὀλ</span>[<span class=\"greek\">ίγ</span>]<span class=\"greek\">ω</span>[<span class=\"greek\">ς</span>]; POxy 1223, 16; Is 10:7 Aq.), dificilmente, por pouco: <span class=\"greek\">ὀλ</span>. <span class=\"greek\">ἀποφεύγειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:18</a> (variante de leitura <span class=\"greek\">ὄντως</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὄλλυμι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὄλλυμι</span>, futuro <span class=\"greek\">ὀλῶ</span>; aoristo <span class=\"greek\">ὤλεσα</span>, JosAs 12:9 cód. A; infinitivo <span class=\"greek\">ὀλέσαι</span> (Just.). Futuro médio: 3ª pessoa singular, <span class=\"greek\">ὀλεῖται</span>; plural, <span class=\"greek\">ὀλοῦνται</span>, LXX; aoristo, 3ª pessoa singular, <span class=\"greek\">ὤλετο</span>; plural, <span class=\"greek\">ὤλοντο</span>, LXX (Hom. e outros; LXX; Just., A I, 25, 2): destruir, com <span class=\"greek\">τινά</span>, alguém (SibOr 5, 509 <span class=\"greek\">πάντας</span> <span class=\"greek\">κακούς</span>), <span class=\"greek\">ἀσεβεῖς</span>, ímpios, 1 Cl 57:7 (Pr 1:32).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλοθρευτής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλοθρευτής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (somente em escritores cristãos; cf. AcPh 130 [Aa II/2, 59, 9]. Sobre a grafia [N. 25 <span class=\"greek\">ὀλε</span>-], ver <span class=\"greek\">ὀλοθρεύω</span>), destruidor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:10</a> (o AT fala de <span class=\"greek\">ὁ</span> <span class=\"greek\">ὀλεθρεύων</span>, Ex 12:23 = <span class=\"hebrew\" dir=\"rtl\">הַמַּשְׁחִית</span>; Wsd 18:25; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:28</a>); trata-se do anjo destruidor, executor da sentença divina de punição, ou talvez de Satanás (MDibelius, Geisterwelt 44f).—DELG s.v. <span class=\"greek\">ὄλλυμι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλοθρεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλοθρεύω</span> (Vett. Val. 123, 11 <span class=\"greek\">ὀλεθρεύει</span>; LXX; TestLevi 13:7; TestJud 6:5; 7:3; Philo, Leg. All. 2, 34; SibOr 5, 304. Sobre sua grafia, ao lado de <span class=\"greek\">ὀλεθρεύω</span> [na LXX, com as formas <span class=\"greek\">ὀλεθρεύσω</span> e aoristo <span class=\"greek\">ὠλέθρευσα</span>], ver B-D-F § 32, 1; W-S. §5, 20d; Mlt-H. 71; Reinhold 40; KBuresch, RhM 46, 1891, 216f), causar destruição completa, destruir, arruinar, com <span class=\"greek\">τινά</span>, alguém; <span class=\"greek\">ὁ</span> <span class=\"greek\">ὀλοθρεύων</span>, o anjo destruidor (ver <span class=\"greek\">ὀλοθρευτής</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:28</a> (com base em Ex 12:23).—DELG s.v. <span class=\"greek\">ὄλλυμι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁλοκαύτωμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁλοκαύτωμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ὅλος</span>, <span class=\"greek\">καίω</span>; não empregado no grego geral [mas <span class=\"greek\">ὁλοκαυτόω</span>, em X. e outros]. Na LXX; TestJob; TestLevi 9:7; Philo, Sacr. Abel. 110; Jos., Bell. 5, 565, Ant. 10, 70. Sobre a formação da palavra, ver Dssm., B 135 [BS 138]). ① Sacrifício cultual em que o animal era inteiramente consumido pelo fogo, holocausto, oferta inteiramente queimada, literalmente (com <span class=\"greek\">θυσία</span> e termos semelhantes), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:33</a>; 1 Cl 18:16 (Ps 50:18); B 2:4, 5 (Is 1:11), 7 (Jer 7:22). Com <span class=\"greek\">περὶ</span> <span class=\"greek\">ἁμαρτίας</span>, «oferta pelo pecado», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:6</a>, 8 (ambos, Ps 39:7). <span class=\"greek\">ὁλ</span>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἁμαρτιῶν</span>, 7:6 (cf. Lev 16:5). <span class=\"greek\">θυσίας</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">αἵματος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κνίσης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁλοκαυτωμάτων</span> <span class=\"greek\">ἐπιτελεῖν</span>, oferecer sacrifícios a Deus com sangue, queima de gordura e holocaustos, Dg 3:5. ② Pessoa condenada à morte pelo fogo devido a sua convicção pessoal, vítima inteiramente queimada, holocausto, extensão figurada de 1: a respeito de Policarpo, <span class=\"greek\">ὁλ</span>. <span class=\"greek\">δεκτὸν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ἡτοιμασμένον</span>, MPol 14:1.—Ver DELG s.v. <span class=\"greek\">καίω</span> e <span class=\"greek\">ὅλο</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁλοκληρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁλοκληρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">ὁλόκληρος</span>; Chrysipp. [Stoic. III 33]; Plut., Mor. 1041e; 1047e <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>; 1063f <span class=\"greek\">ὑγεία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁλ</span>.; Diog. L. 7, 107; SIG 1142, 2 [I/II d.C.] <span class=\"greek\">ὁλ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span>; POxy 123, 6; 1478, 3; BGU 948, 4 com <span class=\"greek\">ὑγία</span>; Is 1:6, variante de leitura), estado de integridade ou bem-estar em todas as partes, inteireza, integridade: acerca da cura de um coxo, <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> … <span class=\"greek\">ἔδωκεν</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁλ</span>. <span class=\"greek\">ταύτην</span>, a fé … lhe deu esta saúde perfeita, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:16</a>. ADebrunner, Philol. 95, ’42, 174–76.—DELG s.v. <span class=\"greek\">ὅλο</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁλόκληρος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁλόκληρος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">ὅλος</span>, <span class=\"greek\">κλῆρος</span>; Pla.; Polyb. 18, 45, 9; Ps.-Lucian, Macrob. 2; Epict. 3, 26, 7; 25; 4, 1, 66; 151; OGI 519, 14; SIG 1009, 10; 1012, 9 e outros, ver New Docs 4, 161f; PLond III, 935, 7 p. 30 [216/17 d.C.]; POxy 57, 13; LXX; Philo, Abr. 47, Spec. Leg. 1, 283; Jos., Ant. 3, 228; 278; 14, 366; Just., D. 69, 7), relativo a algo completo e que satisfaz todas as expectativas, dotado de integridade, inteiro, completo, não danificado, intacto, irrepreensível: <span class=\"greek\">πίστις</span>, fé inabalada, Hm 5, 2, 3; GJs 16:2. Em sentido ético, <span class=\"greek\">ὁλ</span>. <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> … <span class=\"greek\">τηρηθείη</span>, que vosso espírito … seja preservado inteiro ou íntegro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:23</a> (PGM 7, 590 <span class=\"greek\">διαφύλασσέ</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>, <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">ὁλόκληρον</span>.—PvanStempvoort, NTS 7, ’60/61, 262–65: relaciona <span class=\"greek\">πνεῦμα</span> e <span class=\"greek\">ἁγιάσαι</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:23</a>). Com <span class=\"greek\">τέλειος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:4</a>.—B. 919. DELG s.v. <span class=\"greek\">ὅλο</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὀλολύζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὀλολύζω</span>, futuro <span class=\"greek\">ὀλολύξω</span>, LXX; aoristo <span class=\"greek\">ὠλόλυξα</span> (Hom. e outros; PGM 11a, 30; LXX; cf. a forma hebraica hifil igualmente onomatopaica <span class=\"hebrew\" dir=\"rtl\">ילל</span>), gritar em voz alta, tanto de alegria quanto de dor, clamar (<span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, como Lucian, Dial. Deor. 12, 1): <span class=\"greek\">κλαύσατε</span> <span class=\"greek\">ὀλολύζοντες</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ταλαιπωρίαις</span> <span class=\"greek\">ὑμῶν</span>, lamentai e gritai em voz alta por vossas tribulações, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:1</a>. A respeito do telhado de um templo, GJs 24:3.—LDeubner, Ololyge u. Verwandtes: ABA ’41 nº 1.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὅλος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὅλος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Pind. e posteriores [Hom. e Hes. têm a forma jônica <span class=\"greek\">οὖλος</span>]); no NT, nunca em posição atributiva, na maioria das vezes em posição predicativa (W-S. §20, 12a; B-D-F § 275, 2; 4; Rob. 774, cf. 656). ① Relativo a algo completo em sua extensão, todo, inteiro, completo. ⓐ Usado com substantivo sem artigo, ora anteposto, ora posposto: <span class=\"greek\">ὅλ</span>. <span class=\"greek\">οἴκους</span>, famílias inteiras, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:11</a>. <span class=\"greek\">ὅλ</span>. <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">ὑγιῆ</span> <span class=\"greek\">ἐποίησα</span>, curei o corpo inteiro de um homem, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:23</a>.—<span class=\"greek\">ἐνιαυτὸν</span> <span class=\"greek\">ὅλ</span>., durante um ano inteiro, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:26</a>. <span class=\"greek\">διετίαν</span> <span class=\"greek\">ὅλ</span>., durante dois anos completos, 28:30.—<span class=\"greek\">δι</span>’ <span class=\"greek\">ὅλης</span> <span class=\"greek\">νυκτός</span>, durante toda a noite, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:6</a>, variante de leitura (Appian, Liby. 134 §636; Lucian, Ver. Hist. 1, 29; Just., D. 1, 4.—SIG 1171, 6 <span class=\"greek\">δι</span>’ <span class=\"greek\">ὅλης</span> <span class=\"greek\">ἡμέρας</span>; cf. Jos., Ant. 6, 37, Vi. 15 <span class=\"greek\">δι</span>’ <span class=\"greek\">ὅλης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νυκτός</span>; InsPriene 112, 98 <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χειμῶνος</span> <span class=\"greek\">ὅλου</span>). Analogamente, com nomes de cidades sem artigo: <span class=\"greek\">ὅλη</span> <span class=\"greek\">Ἰερουσαλήμ</span>, toda Jerusalém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:31</a>. ⓑ Usado com substantivo que tem artigo. <span class=\"greek\">α</span>. Antes do substantivo: <span class=\"greek\">ὅλ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">περίχωρος</span> <span class=\"greek\">ἐκείνη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:35</a>; cf. GJs 8:3; AcPl Ha 8, 30. <span class=\"greek\">ὅλ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">χώρα</span> <span class=\"greek\">ἐκείνη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:55</a>. <span class=\"greek\">ὅλ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span>, 1:33. <span class=\"greek\">ὅλ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμά</span> <span class=\"greek\">σου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:29f</a>; 6:22f. <span class=\"greek\">ὅλ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">βίος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:43</a>. [<span class=\"greek\">ἐφ</span>’] <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:10</a>. <span class=\"greek\">ὅλ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡμέραν</span>, durante todo o dia (Jos., Ant. 6, 22), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:36</a> (Ps 43:23); 10:21 (Is 65:2). <span class=\"greek\">ἐξ</span> <span class=\"greek\">ὅλης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἰσχύος</span> <span class=\"greek\">ἡμῶν</span>, com todas as nossas forças, 1 Cl 33:8. <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Γαλιλαίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:39</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, Hs 9, 25, 2 (<span class=\"greek\">ὅλ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span>: Wsd 11:22; Aristobulus em Eus., PE 13, 12, 9 [Denis 224, 4; Holladay 176, 5]; EpArist 210; ApcEsdr 1:11 p. 25, 4 Tdf.). <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">καταγγέλλεται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κόσμῳ</span>, vossa fé é anunciada em todo o mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:8</a> (quanto à hipérbole, cf. PLond 891, 9 <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐφημία</span> <span class=\"greek\">σου</span> <span class=\"greek\">περιεκύκλωσεν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> <span class=\"greek\">ὅλον</span>). <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span>, AcPl Ha 4, 20. <span class=\"greek\">β</span>. Depois do substantivo: <span class=\"greek\">ὁ</span> <span class=\"greek\">κόσμος</span> <span class=\"greek\">ὅλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:19</a>; AcPl Ha 3, 7 (TestJob 33:4; Just., D. 127, 2). <span class=\"greek\">τὸ</span> <span class=\"greek\">συνέδριον</span> <span class=\"greek\">ὅλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.59\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:59</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμά</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὅλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:36a</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὅλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:53</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span> <span class=\"greek\">ὅλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:30</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκουμένη</span> <span class=\"greek\">ὅλ</span>., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:10</a>. <span class=\"greek\">γ</span>. O substantivo também pode ser suprido pelo contexto: <span class=\"greek\">ἕως</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐζυμώθη</span> <span class=\"greek\">ὅλον</span> (isto é, <span class=\"greek\">τὸ</span> <span class=\"greek\">ἄλευρον</span>), até toda a massa de farinha ficar levedada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:21</a>. <span class=\"greek\">ἔσται</span> <span class=\"greek\">φωτεινὸν</span> <span class=\"greek\">ὅλον</span> (isto é, <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμά</span> <span class=\"greek\">σου</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:36b</a>.—Semelhantemente, o particípio substantivado: <span class=\"greek\">ἔστιν</span> <span class=\"greek\">καθαρὸς</span> <span class=\"greek\">ὅλος</span> (<span class=\"greek\">ὁ</span> <span class=\"greek\">λελουμένος</span>), aquele que tomou banho está inteiramente limpo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:10</a>. ② Relativo a um grau de completude, inteiramente, completamente; com pronome: <span class=\"greek\">σὺ</span> <span class=\"greek\">ὅλος</span>, tu inteiramente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:34</a>. <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ὅλον</span>, tudo isso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:22</a>; 21:4, variante de leitura; 26:56. <span class=\"greek\">ὅλον</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐπιδείξας</span>, tendo-se exposto inteiramente (ao leão), AcPl Ha 4, 29.—Com preposição: <span class=\"greek\">δι</span>’ <span class=\"greek\">ὅλου</span>, por toda a extensão, completamente (Philo Mech. 60, 25; POxy 53, 10; 1277, 8; PGM 5, 154), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:23</a> (cf. New Docs 3, 63, nº 26). ③ Tudo que existe, o universo, tudo; neutro plural substantivado (3 Macc 6:9; EpArist 201; TestAbr A 20 p. 103, 27 [Stone p. 54]; ApcMos, Philo, Joseph., Just., Tat., Ath.): [<span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλ</span>]<span class=\"greek\">ων</span> <span class=\"greek\">δεσπότης</span>, Ox 1081, 36 (como em TestAbr A, ver acima; ApcMos 37; Jos., Ant. 1, 72; Tat. 5, 1; cf. Just., D. 140, 4). <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">παντοκράτωρ</span>, AcPlCor 2:9. <span class=\"greek\">ὁ</span> … <span class=\"greek\">δεσπότης</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δημιουργὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὅλων</span>, Dg 8:7.—Cf. <span class=\"greek\">πᾶς</span>; ver Schmidt, Syn. IV 549. B. 919. DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0253-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὁλοτελής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὁλοτελής</span>, <span class=\"greek\">ές</span> (<span class=\"greek\">ὅλος</span>, <span class=\"greek\">τέλος</span>; desde [desconsiderando Aristot., De Plantis 817b, na tradução grega tardia de uma versão latina]; Plut., Mor. 909b; Galen XIX p. 162 K.; SIG 814, 45 [67 d.C.]), relativo a ser inteiramente completo, com implicação de alcançar um padrão elevado, completo em todos os aspectos, inteiramente perfeito; acerca de pedras, Hv 3, 6, 4. <span class=\"greek\">ἀποκάλυψις</span>, revelação completa em todos os aspectos, 3, 10, 9; 3, 13, 4b. <span class=\"greek\">ὁλ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span>, m 9:6. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἁγιάσαι</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ὁλοτελεῖς</span>, que Deus vos santifique completamente, em todos os aspectos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:23</a>. <span class=\"greek\">αἱ</span> <span class=\"greek\">ῥάβδοι</span> <span class=\"greek\">ὁλοτελεῖς</span> <span class=\"greek\">χλωραί</span>, ramos muito verdes, Hs 8, 5, 2.—M-M. TW.</p></section></article>"};
